//! Plans metadata over SAME original callable coordinates and raw file loans.
//! Only bounded key/name summaries survive; no Proc/File/AST/source model.
use crate::{reactive_original_source::ReadSource,reactive_reads_native::Failure,plans_policy::{self,PreparedMetadata,MarkerRow},key_policy_control as kc};
use std::io;
struct Control<'a,'s>(&'a ReadSource<'s>);
impl kc::Control for Control<'_,'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{self.0.checkpoint()?;self.0.budget().require().map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;self.0.require()?;Ok(())}fn reserve(&mut self,n:usize)->Result<(),Failure>{self.0.budget().charge(n).map_err(|actual|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,actual)))}fn overflow(&mut self)->Failure{self.0.budget().deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"Plans metadata capacity overflow"))}fn allocation_failed(&mut self)->Failure{self.0.budget().deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"Plans metadata capacity refused"))}}
struct Reader<'a>{relative:String,header:u32,owner:&'a str,name:&'a str,matched:bool}
pub(crate) fn collect(source:&ReadSource<'_>)->Result<PreparedMetadata,Failure>{let mut c=Control(source);kc::Control::checkpoint(&mut c)?;let defines=source.dependency_defines()?;let markers=source.plans_marker_rows()?;let mut out=PreparedMetadata::default();for marker in &markers.markers{out.marker(&MarkerRow{name:&marker.name,args:&marker.args,body:&marker.body},&defines,&mut c)?;}
 let mut readers=Vec::new();source.visit_callables(&["draw","hidden_verbs","reactions","derived","generated_reads","derived_reads"],||source.checkpoint().map_err(Failure::Operational),|call|{kc::Control::checkpoint(&mut c)?;if matches!(call.name,"draw"|"hidden_verbs"){out.legacy_output(call.owner,&mut c)?;}else{let(relative,_)=source.site_line(call.ordinal,1)?;let header=u32::try_from(call.header).map_err(|_|Failure::Unsupported("Plans original reader header line overflow".into()))?;crate::reactive_dependency_fold::row(&mut c,&mut readers)?;readers.push(Reader{relative,header,owner:call.owner,name:call.name,matched:false});}Ok::<_,Failure>(())})?;
 readers.sort_unstable_by(|a,b|(&a.relative,a.header,a.owner,a.name).cmp(&(&b.relative,b.header,b.owner,b.name)));readers.dedup_by(|a,b|a.relative==b.relative&&a.header==b.header&&a.owner==b.owner&&a.name==b.name);
 let completed=source.with_plan_metadata_files(&mut|relative,views,code_source|{kc::Control::checkpoint(&mut c)?;let first=readers.partition_point(|row|row.relative.as_str()<relative);let last=readers.partition_point(|row|row.relative.as_str()<=relative);if !code_source&&first==last{return Ok(true)}let text=views.raw()?;if code_source{out.file(text,&defines,&mut c)?;}for row in &mut readers[first..last]{out.reader(text,row.header,row.owner,row.name,&defines,&mut c)?;row.matched=true;}Ok(true)})?;if !completed||readers.iter().any(|row|!row.matched){return Err(Failure::Operational(io::Error::new(io::ErrorKind::InvalidInput,"Plans requires the genuine original raw file of every issued reader definition")))}
 source.raw_metadata_checked(&mut||source.checkpoint(),&mut|_,event|{if let crate::raw_reactive_metadata_policy::Event::Tracked{name,..}=event{out.tracked(name,&mut c)?;}Ok(())})?;kc::Control::checkpoint(&mut c)?;Ok(out)}
pub(crate) fn generate(source:&ReadSource<'_>,analysis:crate::reactive_dependency_view::Analysis<'_>)->Result<crate::sparse_slots_policy::Output,Failure>{let metadata=collect(source)?;let result=plans_policy::generate_prepared_admitted(analysis,&metadata,source.budget(),&||source.checkpoint());match result{Err(actual)=>Err(Failure::Operational(actual)),Ok(output)=>{kc::Control::checkpoint(&mut Control(source))?;Ok(output)}}}
